function concatenateUint8Arrays(arrays) {
	const totalLength = arrays.reduce((acc, value) => acc + value.length, 0);
	const result = new Uint8Array(totalLength);
	let length = 0;
	for (const array of arrays) {
		result.set(array, length);
		length += array.length;
	}
	return result;
}
